INSERT INTO dump_descriptions (base_key, description) VALUES ('bulldogrework', 'Rebalances Bulldog Revolver damage, ammo, spread, upgrades, and overclocks.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
