INSERT INTO dump_descriptions (base_key, description) VALUES ('muzzleflash_smoke_adjustments', 'Reduces selected weapon muzzle-flash, smoke, and explosion emitters, including the Minigun, Bolt Rifle, and Detpack.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('removeextraneousparticles', 'Removes selected weapon and tool particles, including casing, explosion, projectile, and impact effects.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
